def get_odd_collatz(n):
    def collatz(n):
        if n == 1:
            return [1]
        elif n % 2 == 0:
            return [n] + collatz(n // 2)
        else:
            return [n] + collatz(3 * n + 1)

    return sorted([i for i in collatz(n) if i % 2 != 0])
```

